<script setup lang="ts">
// Day 1: Points — places in Overture Maps whose name contains "鳥取", twinkling on a navy-tinted monochrome globe
import ThreeView, { Color } from '@navaramap/three'
import { DefaultPlugin, type DefaultDescriptions } from '@navaramap/three-default-plugin'
import type { Layer } from '@navaramap/three'
import { LimbGlowMeshDesc, type LimbGlowConfig } from './lib/LimbGlowMeshDesc'
import { StarfieldMeshDesc, type StarfieldConfig } from './lib/StarfieldMeshDesc'

// Generated by scripts/day01/extract_tottori.py and extract_pref_boundaries.py
const dataBase = `${useRuntimeConfig().app.baseURL}data/day01`

const NAVY = '#060b1c'
const SPARKLE = new Color().setStyle('#fff4c8')
const LAND = new Color().setStyle('#1b2236')
const COAST = new Color().setStyle('#7d8bb0')
const BORDER = new Color().setStyle('#4a5880')
const BORDER_TOTTORI = new Color().setStyle('#c9d6ff')

const container = ref<HTMLDivElement>()
let view: ThreeView<DefaultDescriptions> | undefined
let frame = 0

// Stable pseudo-random phase/speed per point so each one twinkles on its own rhythm
function rand(seed: number): number {
  const x = Math.sin(seed * 12.9898) * 43758.5453
  return x - Math.floor(x)
}

function twinkle(batchId: number, t: number): number {
  const speed = 0.6 + rand(batchId) * 1.6
  const phase = rand(batchId + 0.5) * Math.PI * 2
  // Sharpen the sine so points mostly rest dim and flash briefly
  return Math.pow((Math.sin(t * speed + phase) + 1) / 2, 6)
}

onMounted(async () => {
  const v = new ThreeView<DefaultDescriptions>({
    container: container.value!,
    backgroundColor: new Color().setStyle(NAVY),
    animation: true,
  })
  view = v
  const defaultPlugin = new DefaultPlugin()
  v.addPlugin(defaultPlugin)
  await v.init()
  if (view !== v) return // unmounted while initializing
  v.registerMesh('limbGlow', LimbGlowMeshDesc)
  v.registerMesh('starfield', StarfieldMeshDesc)

  v.globe.color = new Color().setStyle(NAVY)
  // Frame Tottori from far enough out to see the whole archipelago and the globe's curve
  v.setCamera({ lng: 134.0, lat: 35.4, height: 0, distance: 2_500_000, heading: 0, pitch: -60, roll: 0 })

  const bloom = v.addEffect({ selectiveBloom: { strength: 1.6, radius: 0.5, threshold: 0 } })

  // A soft halo marks where the globe meets space (the photoreal sky would cost ~8 MB of textures)
  // (typed separately: the view's mesh config union only knows the DefaultPlugin descriptors)
  const limbGlow: LimbGlowConfig = { limbGlow: { color: new Color().setStyle('#5b86ff'), intensity: 0.8, scaleHeight: 80_000 } }
  v.addMesh<LimbGlowMeshDesc>(limbGlow)
  const starfield: StarfieldConfig = { starfield: {} }
  v.addMesh<StarfieldMeshDesc>(starfield)

  // No basemap: a plain ellipsoid (the navy globe) for the clamped vectors to drape onto
  v.addLayer({ type: 'terrain', ellipsoid: {} })

  // Land fill and coastline (Japan from Overture, elsewhere Natural Earth)
  const land = v.addSource({ type: 'geojson', url: `${dataBase}/land.geojson` })
  v.addLayer({ type: 'vector', source: land, polygon: { color: LAND, clampToGround: true } })
  const coastline = v.addSource({ type: 'geojson', url: `${dataBase}/coastline.geojson` })
  v.addLayer({
    type: 'vector',
    source: coastline,
    polyline: { color: COAST, width: 1, clampToGround: true },
  })

  // Prefecture borders, with Tottori's highlighted
  const borders = v.addSource({ type: 'geojson', url: `${dataBase}/pref_boundaries.geojson` })
  const borderLayer = v.addLayer({
    type: 'vector',
    source: borders,
    polyline: { color: BORDER, width: 1, clampToGround: true },
  })
  borderLayer.on('featureUpdated', ({ evaluator }) => {
    evaluator.evaluate(
      ({ properties }) => {
        const tottori = properties?.['tottori'] === true
        return { color: tottori ? BORDER_TOTTORI : BORDER, width: tottori ? 2.5 : 1 }
      },
      { filters: ['tottori'] },
    )
  })

  // Places — each point's size and glow pulse independently
  const places = v.addSource({ type: 'geojson', url: `${dataBase}/tottori_places.geojson` })
  const placeLayer: Layer = v.addLayer({
    type: 'vector',
    source: places,
    point: {
      color: SPARKLE,
      size: 4,
      sizeInMeters: false,
      clampToGround: false,
      // The default depth offset lets points just behind the limb show through; lift them slightly instead
      offsetDepth: false,
      height: 15_000,
      center: { x: 0.5, y: 0.5 },
      declutter: false,
      emissiveColor: SPARKLE,
      effectIds: [bloom.id],
    },
  })
  let t = 0
  placeLayer.on('featureUpdated', ({ evaluator }) => {
    evaluator.evaluate(
      ({ batchId }) => {
        const k = twinkle(batchId, t)
        return { size: 2.5 + 5.5 * k, emissive: SPARKLE, emissiveIntensity: 0.3 + 2.7 * k, opacity: 0.55 + 0.45 * k }
      },
      { filters: [] },
    )
  })

  let last = 0
  const tick = (now: number) => {
    frame = requestAnimationFrame(tick)
    if (now - last < 50) return // re-evaluate ~20 fps; plenty for a twinkle
    last = now
    t = now / 1000
    placeLayer.forceUpdate()
  }
  frame = requestAnimationFrame(tick)

  v.attribution?.add([
    {
      attributionHtml:
        '© <a href="https://overturemaps.org/">Overture Maps Foundation</a> · © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
  ])
})

onBeforeUnmount(() => {
  cancelAnimationFrame(frame)
  view?.dispose()
  view = undefined
})
</script>

<template>
  <div ref="container" class="map-canvas" />
</template>
